pub(crate) fn apply_engine_mutation_durable<T, F>(
    engine: &mut SingleNodeEngine,
    backend: &AnyStateBackend,
    timestamp_ms: u64,
    mode: SyncMode,
    f: F,
) -> Result<T, DurableCommitError>
where
    F: FnOnce(&mut SingleNodeEngine) -> T,
{
    let mut clone = engine.clone();
    let result = f(&mut clone);
    let meta = engine_commit_meta(&clone, ENGINE_CANONICAL_RECORD_VERSION, timestamp_ms)?;
    let plan = build_durable_commit_plan(engine, &clone, meta)?;
    apply_durable_commit_plan_with_mode(backend, plan, mode)?;
    *engine = clone;
    Ok(result)
}

fn with_engine_mutation<T, F, P>(
    &self,
    timestamp_ms: u64,
    mode: SyncMode,
    profile_kind: Option<EngineLockProfileKind>,
    f: F,
    on_durable_error: P,
) -> LockResult<T>
where
    F: FnOnce(&mut SingleNodeEngine) -> T,
    P: FnOnce(crate::persistence::DurableCommitError) -> T,
{
    let backend = self.durable_backend.clone();
    let wait_started = Instant::now();
    match self.compat_lock(None) {
        Ok(mut engine) => {
            let acquired_at = Instant::now();
            let result = if let Some(backend) = backend {
                match crate::persistence::apply_engine_mutation_durable(
                    &mut engine,
                    &backend,
                    timestamp_ms,
                    mode,
                    f,
                ) {
                    Ok(result) => result,
                    Err(error) => on_durable_error(error),
                }
            } else {
                f(&mut engine)
            };
            let hold_ns = duration_as_nanos_u64(acquired_at.elapsed());
            drop(engine);
            if let Some(profile_kind) = profile_kind {
                self.record_lock_profile(
                    profile_kind,
                    duration_as_nanos_u64(acquired_at.duration_since(wait_started)),
                    hold_ns,
                );
            }
            Ok(result)
        }
        Err(poisoned) => {
            let acquired_at = Instant::now();
            let mut engine = poisoned.into_inner();
            let result = if let Some(backend) = backend {
                match crate::persistence::apply_engine_mutation_durable(
                    &mut engine,
                    &backend,
                    timestamp_ms,
                    mode,
                    f,
                ) {
                    Ok(result) => result,
                    Err(error) => on_durable_error(error),
                }
            } else {
                f(&mut engine)
            };
            let hold_ns = duration_as_nanos_u64(acquired_at.elapsed());
            if let Some(profile_kind) = profile_kind {
                self.record_lock_profile(
                    profile_kind,
                    duration_as_nanos_u64(acquired_at.duration_since(wait_started)),
                    hold_ns,
                );
            }
            Err(PoisonError::new(result))
        }
    }
}

pub fn apply_mahi_committed_blocks_merged(
    &self,
    blocks: &[MahiBlock],
) -> LockResult<Result<Hash, crate::NodeError>> {
    let _policy = self.policy.track_lock();
    let _dag = self.dag.track_lock();
    let _mempool = self.mempool.track_lock();
    let _market_state = self.market_state.track_lock();
    let _chain_tail = self.chain_tail.track_lock();
    let _events = self.events.track_lock();
    let mutation_timestamp_ms = blocks
        .iter()
        .map(|block| block.timestamp_ms)
        .max()
        .unwrap_or(0);
    self.with_engine_mutation(
        mutation_timestamp_ms,
        SyncMode::Sync,
        None,
        |engine| {
            engine
                .apply_mahi_committed_blocks_merged(blocks)
                .map(block_hash)
        },
        durable_error_result,
    )
}

pub(super) fn filter_mahi_intent_payload<'a, I>(
    &self,
    intents: I,
    market_marks: &BTreeMap<u64, OraclePrice>,
    market_index_prices: &BTreeMap<u64, OraclePrice>,
    positions_after_funding: &BTreeMap<(u64, u64), PositionLedger>,
    block_number: u64,
    timestamp_ms: u64,
) -> (Vec<BlockItem>, Vec<RejectedIntent>)
where
    I: IntoIterator<Item = &'a SignedIntent>,
{
    let mut expected_nonces = BTreeMap::new();
    let mut burned_policies = BTreeSet::new();
    let mut simulated_policy_store = self.policy_store.clone();
    let mut simulated_order_books = BTreeMap::new();
    let mut simulated_resting_order_mandates = self.resting_order_mandates.clone();
    let mut simulated_isolated_collateral = BTreeMap::new();
    let mut items = Vec::new();
    let mut rejected = Vec::new();

    for signed_intent in intents {
        let policy_id = signed_intent.intent.policy_id;
        if burned_policies.contains(&policy_id) {
            rejected.push(RejectedIntent {
                signed_intent: signed_intent.clone(),
                reason: IntentRejectionReason::PredecessorIntentRejected,
                order_reason: None,
            });
            continue;
        }

        let expected_nonce = expected_nonces
            .entry(policy_id)
            .or_insert_with(|| self.policy_store.next_intent_nonce(policy_id).unwrap_or(1));
        if signed_intent.intent.nonce != *expected_nonce {
            continue;
        }

        let mut next_policy_store = simulated_policy_store.clone();
        let mut next_order_books = simulated_order_books.clone();
        let mut next_resting_order_mandates = simulated_resting_order_mandates.clone();
        let mut next_isolated_collateral = simulated_isolated_collateral.clone();
        match simulate_intent_on_runtime_state(
            &mut next_policy_store,
            &self.mandates,
            &self.delegations,
            &self.account_operators,
            simulation_order_books_for_intent(
                &mut next_order_books,
                &self.order_books,
                signed_intent,
            ),
            &mut next_resting_order_mandates,
            simulation_collateral_for_intent(
                &mut next_isolated_collateral,
                &self.isolated_collateral,
                signed_intent,
            ),
            &self.frozen_accounts,
            &self.markets,
            &self.paused_markets,
            market_marks,
            market_index_prices,
            &self.market_oracle_config,
            positions_after_funding,
            signed_intent,
            self.head().header.chain_id,
            block_number,
            timestamp_ms,
            PolicyAdmissionCommitMode::PreverifiedSession,
        ) {
            Ok(_) => {
                simulated_policy_store = next_policy_store;
                simulated_order_books = next_order_books;
                simulated_resting_order_mandates = next_resting_order_mandates;
                simulated_isolated_collateral = next_isolated_collateral;
                items.push(BlockItem::Intent(signed_intent.clone()));
                *expected_nonce = expected_nonce.saturating_add(1);
            }
            Err(error) if transient_intent_blocker(&error) => {}
            Err(error) => {
                let (reason, order_reason) = rejection_context_from_node_error(&error);
                rejected.push(RejectedIntent {
                    signed_intent: signed_intent.clone(),
                    reason,
                    order_reason,
                });
                burned_policies.insert(policy_id);
            }
        }
    }

    (items, rejected)
}

