fn drain_ready_execution_for_batch(&mut self, execution_batch_size: usize) -> Vec<MahiBlock> {
    let execution_batch_size = execution_batch_size.max(1);
    if execution_batch_size == 1 {
        return self.drain_ready_execution();
    }

    let mut verified = 0_usize;
    for block in &self.pending_execution {
        let status = self
            .verification_status
            .get(&block.block_ref())
            .copied()
            .unwrap_or(MahiBlockVerificationStatus::Pending);
        if status != MahiBlockVerificationStatus::Verified {
            break;
        }
        verified = verified.saturating_add(1);
    }

    let executable = verified - (verified % execution_batch_size);
    let mut ready = Vec::with_capacity(executable);
    for _ in 0..executable {
        if let Some(block) = self.pending_execution.pop_front() {
            ready.push(block);
        }
    }
    ready
}

fn phase6_inplace_resting_commit_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var(PHASE6_INPLACE_RESTING_COMMIT_ENV)
            .map(|value| value != "0" && !value.eq_ignore_ascii_case("false"))
            .unwrap_or(true)
    })
}

pub fn remove_block(&mut self, body: &BlockBody) {
    for item in &body.items {
        if let BlockItem::Intent(signed_intent) = item {
            let id = intent_id(signed_intent);
            self.known_intents.remove(&id);
            self.intents_by_order.remove(&IntentOrderKey {
                policy_id: signed_intent.intent.policy_id,
                nonce: signed_intent.intent.nonce,
                intent_id: id,
            });
        }
    }
}

pub(super) fn remove_rejected(&mut self, rejected: &[RejectedIntent]) {
    for rejected_intent in rejected {
        let signed_intent = &rejected_intent.signed_intent;
        let id = intent_id(signed_intent);
        self.known_intents.remove(&id);
        self.intents_by_order.remove(&IntentOrderKey {
            policy_id: signed_intent.intent.policy_id,
            nonce: signed_intent.intent.nonce,
            intent_id: id,
        });
    }
}

